const raw = ($json.content && $json.content[0] && $json.content[0].text) || '{}';
let triage;
try { triage = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch (e) { triage = { category: 'unknown', severity: 3, description: raw.slice(0, 180), required_skill: 'general' }; }
const loc  = $('MultiSet - Localize Snapshot').first().json;
const el   = $('Find IFC Element').first().json;
const meta = $('Prepare Image & Metadata').first().json;
return [{ json: {
  ...triage,
  position: loc.position, confidence: loc.confidence,
  mapCode: (loc.mapCodes || [])[0] || 'REPLACE_WITH_MULTISET_MAP_CODE',
  element: el, reporterEmail: meta.reporterEmail, photoUrl: meta.photoUrl
} }];

const triage=$input.first().json;
const sourceKey=String($('Drive Trigger - New Snapshot').first().json.id || '');
if(!sourceKey) throw new Error('Drive source ID is required for idempotent ticket creation.');
if(!triage.element?.global_id || !triage.position || ![triage.position.x,triage.position.y,triage.position.z,triage.confidence].every(Number.isFinite)) throw new Error('Phase B requires valid localization.');
if(!Number.isInteger(triage.severity) || triage.severity<1 || triage.severity>5 || !['carpentry','plumbing','electrical','hvac','general'].includes(triage.required_skill)) throw new Error('Invalid Phase A triage contract.');
return [{json:{sourceKey,triage,ticketId:null}}];

